"import { defineNuxtConfig } from 'nuxt/config'

export default defineNuxtConfig({
  // SPA mode
  ssr: false,

  // Source directory
  srcDir: 'src',

  // Nuxt 4 compatibility configuration
  future: {
    compatibilityVersion: 4,
  },

  // Directory layout mappings
  dir: {
    app: 'app', // Keeps app.vue and router.options.ts in src/app/
    layouts: '../layouts',
    middleware: '../middleware',
    plugins: '../plugins'
  },

  // Auto-import directories relative to srcDir (src/)
  imports: {
    dirs: [
      'stores',
      'composables'
    ]
  },

  // Modules
  modules: [
    '@pinia/nuxt',
    '@nuxtjs/tailwindcss'
  ],

  // Extending our feature modules as Nuxt Layers
  extends: [
    './src/modules/analytics',
    './src/modules/feedback'
  ],

  // Tailwind configuration
  tailwindcss: {
    exposeConfig: true,
    viewer: false
  },

  // Nuxt DevServer configuration
  devServer: {
    port: 3000
  },

  // Runtime public config for API
  runtimeConfig: {
    public: {
      apiBaseUrl: '/api/v1' // Uses built-in Nitro server routes for mock API
    }
  },

  // Vite configuration
  vite: {
    optimizeDeps: {
      include: ['chart.js']
    }
  }
})
"

