"import type { RouterConfig } from '@nuxt/schema'

export default <RouterConfig> {
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    }
    if (to.hash) {
      return {
        el: to.hash,
        behavior: 'smooth',
      }
    }
    return { top: 0, left: 0, behavior: 'smooth' }
  }
}
"

"import { defineStore } from 'pinia'
import { ref } from 'vue'

export interface Toast {
  id: string
  message: string
  type: 'success' | 'error' | 'warning' | 'info'
}

export const useNotificationsStore = defineStore('notifications', () => {
  const notifications = ref([])

  function add(message, type = 'info') {
    const id = Date.now().toString() + Math.random().toString(36).substring(2, 9)
    notifications.value.push({ id, message, type })

    // Auto-remove after 4000ms
    setTimeout(() => {
      remove(id)
    }, 4000)
  }

  const success = (message) => add(message, 'success')
  const error = (message) => add(message, 'error')
  const warning = (message) => add(message, 'warning')
  const info = (message) => add(message, 'info')

  function remove(id) {
    notifications.value = notifications.value.filter((n) => n.id !== id)
  }

  return { notifications, add, success, error, warning, info, remove }
})
"

"import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useCookie } from '#app'

export interface User {
  id: number
  name: string
  email: string
  role: 'superadmin' | 'merchant'
}

export interface Company {
  id: number
  name: string
  gstin: string | null
  is_subscription_active: boolean
  subscription_expires_at: string
}

export const useAuthStore = defineStore('auth', () => {
  const token = useCookie('auth_token', { maxAge: 60 * 60 * 24 * 7, path: '/' })
  const user = ref(null)
  const company = ref(null)

  const isAuthenticated = computed(() => !!token.value)
  const isSubscriptionActive = computed(() => company.value?.is_subscription_active ?? false)

  function logout() {
    token.value = null
    user.value = null
    company.value = null
  }

  function setSubscriptionStatus(status: boolean) {
    if (company.value) {
      company.value.is_subscription_active = status
    }
  }

  return {
    token,
    user,
    company,
    isAuthenticated,
    isSubscriptionActive,
    logout,
    setSubscriptionStatus
  }
})
"

"import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

export interface Location {
  id: number
  name: string
  address: string
  city: string
}

export const useLocationsStore = defineStore('locations', () => {
  const locations = ref([])
  const currentLocationId = ref(null)
  const loading = ref(false)

  const currentLocation = computed(() => {
    if (currentLocationId.value === null) return null
    // Support "All Locations" representation if id is 0 or -1, or if it matches a real item
    return locations.value.find((l) => l.id === currentLocationId.value) || null
  })

  async function fetchLocations() {
    const api = useApi()
    loading.value = true
    try {
      const data = await api('/locations')
      locations.value = data
      // If we have locations, auto-set default selection to first element
      if (locations.value.length > 0) {
        if (currentLocationId.value === null || !locations.value.some(l => l.id === currentLocationId.value)) {
          // Default to first location
          currentLocationId.value = locations.value[0].id
        }
      } else {
        currentLocationId.value = null
      }
    } catch (err) {
      console.error('Failed to fetch locations:', err)
    } finally {
      loading.value = false
    }
  }

  function setCurrentLocationId(id) {
    currentLocationId.value = id
  }

  return {
    locations,
    currentLocationId,
    loading,
    currentLocation,
    fetchLocations,
    setCurrentLocationId
  }
})
"

"import { useRuntimeConfig, navigateTo } from '#app'

export const useApi = () => {
  const authStore = useAuthStore()
  const runtimeConfig = useRuntimeConfig()

  return $fetch.create({
    baseURL: (runtimeConfig.public.apiBaseUrl as string) || 'http://localhost:8000/api/v1',
    async onRequest({ options }) {
      if (authStore.token) {
        options.headers = {
          ...options.headers,
          Authorization: `Bearer ${authStore.token}`,
          Accept: 'application/json',
        }
      }
    },
    async onResponseError({ response }) {
      if (response.status === 419 || response.status === 401) {
        authStore.logout()
        await navigateTo('/auth/login')
      }
      if (response.status === 403 && response._data?.error_code === 'SUBSCRIPTION_EXPIRED') {
        authStore.setSubscriptionStatus(false)
        await navigateTo('/billing/expired')
      }
    }
  })
}
"

"export const usePhoneFormatter = () => {
  const formatIndianPhone = (phone: string | number): string => {
    if (!phone) return ''

    // Remove all non-digit characters
    let cleaned = phone.toString().replace(/\D/g, '')

    // If it is 12 digits starting with 91 (e.g. 9198765-43210)
    if (cleaned.length === 12 && cleaned.startsWith('91')) {
      const part1 = cleaned.substring(2, 7)
      const part2 = cleaned.substring(7)
      return `+91 ${part1}-${part2}`
    }

    // If it is 10 digits (e.g. 9876543210)
    if (cleaned.length === 10) {
      const part1 = cleaned.substring(0, 5)
      const part2 = cleaned.substring(5)
      return `+91 ${part1}-${part2}`
    }

    // Fallback if formatting doesn't fit standard pattern
    return phone.toString()
  }

  return {
    formatIndianPhone
  }
}
"

"import { defineNuxtRouteMiddleware, navigateTo } from '#app'

export default defineNuxtRouteMiddleware(async (to, from) => {
  const authStore = useAuthStore()

  // If token is missing, redirect to login
  if (!authStore.token) {
    return navigateTo('/auth/login')
  }

  // If token exists but user state is null, fetch user details
  if (authStore.token && !authStore.user) {
    try {
      const api = useApi()
      const data = await api('/auth/me')
      authStore.user = data.user
      authStore.company = data.company
    } catch (err) {
      console.error('Failed to restore user session:', err)
      authStore.logout()
      return navigateTo('/auth/login')
    }
  }

  // If subscription has expired, force redirect to billing screen
  if (!authStore.isSubscriptionActive && to.path !== '/billing/expired') {
    return navigateTo('/billing/expired')
  }
})
"

"import { defineNuxtRouteMiddleware, navigateTo } from '#app'

export default defineNuxtRouteMiddleware((to, from) => {
  const authStore = useAuthStore()

  // Redirect to dashboard if user is logged in
  if (authStore.isAuthenticated) {
    return navigateTo('/analytics')
  }
})
"

