"<?php

namespace App\Http\Controllers\Api\V1;

use App\Http\Controllers\Controller;
use App\Models\QrCode;
use App\Models\ReviewSession;
use Illuminate\Http\Request;
use Carbon\Carbon;

class AnalyticsController extends Controller
{
    /**
     * Get aggregated metrics for the company.
     * GET /api/v1/analytics
     */
    public function index(Request $request)
    {
        $company = $request->user()->company;

        if (!$company) {
            return response()->json(['message' => 'Authenticated user is not assigned to a company.'], 403);
        }

        $locationIds = $company->locations()->pluck('id');

        // Filter by location_id if specified in query
        $filteredLocationId = null;
        if ($request->filled('locationId')) {
            $locId = (int) $request->locationId;
            if ($locationIds->contains($locId)) {
                $filteredLocationId = $locId;
            }
        }

        // 1. Calculate scans
        $scansQuery = QrCode::query();
        if ($filteredLocationId) {
            $scansQuery->where('location_id', $filteredLocationId);
        } else {
            $scansQuery->whereIn('location_id', $locationIds);
        }
        $totalScanCount = (int) $scansQuery->sum('scan_count');

        // Determine period (7d or 30d)
        $period = $request->query('period', '7d');
        $daysCount = $period === '30d' ? 30 : 7;

        $now = Carbon::now();
        $currentStart = $now->copy()->subDays($daysCount)->startOfDay();
        $currentEnd = $now->copy()->endOfDay();

        $prevStart = $now->copy()->subDays($daysCount * 2)->startOfDay();
        $prevEnd = $now->copy()->subDays($daysCount)->endOfDay();

        // 2. Query for current and previous review sessions
        $baseSessionQuery = ReviewSession::query();
