"<?php

namespace App\Http\Controllers\Api\V1;

use App\Http\Controllers\Controller;
use App\Models\QrCode;
use App\Models\ReviewSession;
use Illuminate\Http\Request;

class AnalyticsController extends Controller
{
    /**
     * Get aggregated metrics for the company.
     * GET /api/v1/analytics
     */
    public function index(Request $request)
    {
        $company = $request->user()->company;

        if (!$company) {
            return response()->json(['message' => 'Authenticated user is not assigned to a company.'], 403);
        }

        $locationIds = $company->locations()->pluck('id');

        // 1. Calculate sum of scan_count from all company QR codes
        $totalScanCount = QrCode::whereIn('location_id', $locationIds)->sum('scan_count');

        // 2. Query for review sessions with optional date filtering
        $sessionQuery = ReviewSession::whereIn('location_id', $locationIds);

        if ($request->filled('date_from')) {
            $sessionQuery->where('created_at', '>=', $request->date_from . ' 00:00:00');
        }

        if ($request->filled('date_to')) {
            $sessionQuery->where('created_at', '<=', $request->date_to . ' 23:59:59');
        }

        // 3. Count positive redirects (conversions to Maps)
        $positiveRedirectCount = (clone $sessionQuery)
            ->where('status', 'positive_redirect')
            ->count();

        // 4. Count negative forms filled (intercepted negative ratings)
        $negativeFeedbackCount = (clone $sessionQuery)
            ->where('status', 'negative_form_filled')
            ->count();

        return response()->json([
            'total_scan_count' => (int) $totalScanCount,
            'positive_redirect_count' => $positiveRedirectCount,
            'negative_feedback_count' => $negativeFeedbackCount,
        ], 200);
    }
}"

